From d9a027674734f2ee57a4fa8d3f58aad4bc0c7967 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 10:22:21 +0100
Subject: [PATCH] VolumeFeedback: play one chime at a time when changing volume
 quickly

Cancelling the chime on every volume step made it pop, and letting the
chimes overlap instead piled them up. Now a step that comes while one is
still playing waits for it to end, and only the latest step is played.

BUG: 505885
---
 src/volumefeedback.cpp | 19 ++++++++++++++++++-
 src/volumefeedback.h   |  3 +++
 2 files changed, 21 insertions(+), 1 deletion(-)

diff --git a/src/volumefeedback.cpp b/src/volumefeedback.cpp
index 5f40fdba..4aa291b3 100644
--- a/src/volumefeedback.cpp
+++ b/src/volumefeedback.cpp
@@ -9,6 +9,8 @@
 #include "canberracontext.h"
 #include "soundthemeconfig.h"

+constexpr int cindex = 2; // Note "2" is simply the index we've picked. It's somewhat irrelevant.
+
 VolumeFeedback::VolumeFeedback(QObject *parent)
     : QObject(parent)
     , m_config(new SoundThemeConfig(this))
@@ -20,6 +22,12 @@ VolumeFeedback::VolumeFeedback(QObject *parent)

     connect(m_config, &SoundThemeConfig::soundThemeChanged, this, &VolumeFeedback::updateCachedSound);
     updateCachedSound();
+
+    m_pendingTimer.setSingleShot(true);
+    m_pendingTimer.setInterval(20);
+    connect(&m_pendingTimer, &QTimer::timeout, this, [this] {
+        play(m_pendingSinkIndex);
+    });
 }

 VolumeFeedback::~VolumeFeedback()
@@ -40,7 +48,16 @@ void VolumeFeedback::play(quint32 sinkIndex)
         return;
     }

-    const int cindex = 2; // Note "2" is simply the index we've picked. It's somewhat irrelevant.
+    // Cancelling a chime that is still playing makes it pop, and letting chimes
+    // overlap piles them up, so play the latest one once the current one is done.
+    int playing = 0;
+    ca_context_playing(context, cindex, &playing);
+    if (playing) {
+        m_pendingSinkIndex = sinkIndex;
+        m_pendingTimer.start();
+        return;
+    }
+
     char dev[64];
     snprintf(dev, sizeof(dev), "%lu", (unsigned long)sinkIndex);
     ca_context_change_device(context, dev);
diff --git a/src/volumefeedback.h b/src/volumefeedback.h
index f56d7552..5b33787f 100644
--- a/src/volumefeedback.h
+++ b/src/volumefeedback.h
@@ -8,6 +8,7 @@
 #define VOLUMEFEEDBACK_H

 #include <QObject>
+#include <QTimer>
 #include <qqmlregistration.h>

 #include <canberra.h>
@@ -34,6 +35,8 @@ private Q_SLOTS:

 private:
     SoundThemeConfig *const m_config;
+    QTimer m_pendingTimer;
+    quint32 m_pendingSinkIndex = 0;
 };

 #endif // VOLUMEFEEDBACK_H
